std::size_t glyph_index(uint32_t codepoint) noexcept {
    if (codepoint >= 0x20U && codepoint <= 0x7EU) return codepoint - 0x20U;
    switch (codepoint) {
    case 0x00B0U: return 95U;
    case 0x2212U: return 96U;
    case 0x2022U: return 97U;
    case 0x2190U: return 98U;
    case 0x2192U: return 99U;
    case 0x2713U: return 100U;
    default: return 31U;
    }
}

